<?php
if(PHP_SAPI!=='cli')exit;ob_start();require 'C:/xampp/htdocs/boticav1/config/database.php';$db=appPdoConnection();$programmer=$db->query("SELECT u.Usuario FROM Seg_Usuario u JOIN Seg_UsuarioPerfil p ON p.IdUsuarioPerfil=u.IdUsuarioPerfil WHERE UPPER(TRIM(p.UsuarioPerfil))='PROGRAMADOR' AND COALESCE(u.Anulado,0)=0 LIMIT 1")->fetchColumn();$sessions=[];
function callDiary($path,$id,$post=null,$csrf=''){$headers='Cookie: PHPSESSID='.$id;if($csrf)$headers.="\r\nX-Diario-CSRF: ".$csrf;$headers.="\r\nContent-Type: application/json";$c=stream_context_create(['http'=>['ignore_errors'=>true,'follow_location'=>0,'timeout'=>10,'method'=>$post===null?'GET':'POST','header'=>$headers,'content'=>$post===null?'':json_encode($post)]]);$body=file_get_contents('http://localhost'.$path,false,$c);return [(int)explode(' ',$http_response_header[0])[1],$body];}
try{foreach(array_filter(['admin','superadmin',$programmer]) as $user){$id='diaryrole'.bin2hex(random_bytes(12));session_id($id);session_start();$_SESSION=['user'=>$user,'idPerfil'=>1,'idAlmacen'=>1,'hostUrl'=>'http://localhost','expire'=>time()+120,'permisos'=>[]];session_write_close();$sessions[]=$id;[$status,$raw]=callDiary('/api/index.php/diario/contexto?ligero=1',$id);$ctx=json_decode($raw,true);if($status!==200)throw new RuntimeException('Context HTTP '.$status.' '.$raw);if($user==='admin'){if(!empty($ctx['admin'])||!empty($ctx['tareasHabilitadas']))throw new RuntimeException('Client granted tasks');if(callDiary('/api/index.php/diario/tareas',$id)[0]!==403)throw new RuntimeException('Client task read allowed');if(callDiary('/api/index.php/diario/tareas',$id,[],$ctx['csrf'])[0]!==403)throw new RuntimeException('Client task write allowed');$rem=json_decode(callDiary('/api/index.php/diario/recordatorios',$id)[1],true);if($rem['tareas']!==[])throw new RuntimeException('Client reminder leak');if(callDiary('/views/diario.php',$id)[0]!==302)throw new RuntimeException('Client diary page not redirected');$header=callDiary('/views/contabilidad.php',$id)[1];if(strpos($header,'id="diario-reportes-menu"')!==false)throw new RuntimeException('Client diary menu visible');if(callDiary('/api/index.php/support/context',$id)[0]!==200)throw new RuntimeException('Client tickets unavailable');}else{if(empty($ctx['tareasHabilitadas']))throw new RuntimeException('Staff diary denied');if(callDiary('/api/index.php/diario/tareas',$id)[0]!==200)throw new RuntimeException('Staff tasks unavailable');if(($user==='superadmin')!==$ctx['admin'])throw new RuntimeException('Wrong task administrator role');}echo 'PASS '.($user==='admin'?'client: no task read/write, empty reminders, no menu, support retained':'staff: task access retained').PHP_EOL;}}finally{foreach($sessions as $id){session_id($id);session_start();$_SESSION=[];session_destroy();}}
